  tagsByProfile: Map<ProfileKey, string[]>,
  profile: string | { expire?: number } | undefined
): ProfileKey {
  let existingKey = undefined;
  for (const [key] of tagsByProfile) {
    if (
      typeof key === "string" &&
      typeof profile === "string" &&
      key === profile
    ) {
      existingKey = key;
      break;
    }
    if (
      typeof key === "object" &&
      typeof profile === "object" &&
      JSON.stringify(key) === JSON.stringify(profile)
    ) {
      existingKey = key;
      break;
    }
    if (key === profile) {
      existingKey = key;
      break;
    }
  }
  return existingKey;
}

